// v1 — 이것으로 파일을 썼다
public class Member implements Serializable {
    public String name; public int age;
}

// v2 — 이것으로 그 파일을 읽었다
public class Member implements Serializable {
    public String name; public int age; public String email;   // 한 줄 추가
}

public class Member implements Serializable {
    private static final long serialVersionUID = 1L;   // 양쪽 판에 같은 값
    public String name; public int age;
}

// v4 는 여기에 email 필드만 추가했다. UID 는 그대로 1L.
